head.script:


scwin.onpageload = function() {
    inputCalendar1.setValue("20250815");
}

scwin.onpageunload = function() {

}

scwin.trigger1_onclick = function() {
    var date = inputCalendar1.getValue();
    var rDate = WebSquare.date.toLunar(date);
    input1.setValue(date);
    input2.setValue(rDate);
}

scwin.trigger2_onclick = function() {
    var date = inputCalendar1.getValue();
    var rDate = WebSquare.date.toSolar(date);
    input1.setValue(rDate);
    input2.setValue(date);
}

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('input1').value == '20251006';
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
